function drawCurrents(result){const c=els.currents,ctx=c.getContext('2d'),W=c.width,H=c.height;ctx.clearRect(0,0,W,H);ctx.fillStyle='#0b0d11';ctx.fillRect(0,0,W,H);const vals=(result.segment_currents_a||[]).map(z=>Math.hypot(z.re,z.im));if(!vals.length)return;const m=Math.max(...vals,1e-12),pad=35,bw=(W-2*pad)/vals.length;ctx.strokeStyle='#202735';for(let k=0;k<=4;k++){const y=pad+(H-2*pad)*k/4;ctx.beginPath();ctx.moveTo(pad,y);ctx.lineTo(W-pad,y);ctx.stroke()}ctx.fillStyle='#5ba0ff';vals.forEach((v,i)=>{const h=(H-2*pad)*v/m;ctx.fillRect(pad+i*bw,H-pad-h,Math.max(1,bw*.72),h)});ctx.fillStyle='#798499';ctx.font='12px system-ui';ctx.fillText(`max |I| = ${m.toExponential(3)} A`,pad,20);ctx.fillText(`${vals.length} segments`,W-130,H-12)}
