async function runSweep(){setWorkspaceView('solve');try{const p=project();updateMeta(p);const startHz=Number(els.sweepStart.value)*1e6,stopHz=Number(els.sweepStop.value)*1e6,points=Number(els.sweepPoints.value),parallel_workers=Number(els.parallelWorkers.value);if(!(parallel_workers>=1&&parallel_workers<=16))throw new Error('Workers: 1…16');if(!(startHz>0&&stopHz>=startHz&&points>=2))throw new Error('Проверь диапазон Sweep');els.runSweep.disabled=true;status('sweep…');const j=await api('/api/sweep',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project:p,kernel,start_hz:startHz,stop_hz:stopHz,points,parallel_workers})});const sw=j.sweep;lastSweep=sw;drawSweep(sw);if(lastMeasurement)els.measurementCompare.disabled=false;els.sweepSummary.textContent=`res ${fmt(sw.resonance_frequency_hz/1e6,3)} MHz · min S11 ${fmt(sw.min_s11_db,2)} dB @ ${fmt(sw.min_s11_frequency_hz/1e6,3)} MHz · BW10 ${fmt(sw.bandwidth_10db_hz/1e6,3)} MHz · ${sw.execution_workers}w${j.cache_hit?' · cache':''}`;status(j.cache_hit?'sweep из кэша':'sweep завершён','ok')}catch(e){status('ошибка sweep','err');els.diag.textContent=String(e.message||e)}finally{els.runSweep.disabled=false}}

