function geometryPointerDown(ev){try{const p=project(),wires=p.wires||[],pt=geometryCanvasPoint(ev),view=geometryView||geometryTransform(p);let endpoint=null,best=14;for(const w of wires){for(const key of['start_m','end_m']){const q=view.toScreen(w[key]),d=Math.hypot(pt.x-q.x,pt.y-q.y);if(d<best){best=d;endpoint={wireId:w.id,key}}}}if(endpoint){selectedWireId=endpoint.wireId;geometryDrag={wireId:endpoint.wireId,key:endpoint.key,view:{bounds:{...view.bounds}}};els.geometryCanvas.setPointerCapture?.(ev.pointerId);renderGeometry(p);ev.preventDefault();return}let hit=null,hd=12;for(const w of wires){const a=view.toScreen(w.start_m),b=view.toScreen(w.end_m),d=geometryDistanceToSegment(pt.x,pt.y,a,b);if(d<hd){hd=d;hit=w.id}}if(hit){selectedWireId=hit;renderGeometry(p);ev.preventDefault()}}catch(e){status('ошибка выбора','err')}}
function geometryPointerMove(ev){if(!geometryDrag)return;try{const p=project(),w=(p.wires||[]).find(x=>x.id===geometryDrag.wireId);if(!w)return;const pt=geometryCanvasPoint(ev),view=geometryTransform(p,geometryDrag.view),base=w[geometryDrag.key];w[geometryDrag.key]=view.fromScreen(pt.x,pt.y,base);els.editor.value=JSON.stringify(p,null,2);updateMeta(p);status('геометрия изменена · расчёт нужно повторить');ev.preventDefault()}catch(e){status('ошибка drag','err')}}
function geometryPointerUp(ev){if(!geometryDrag)return;geometryDrag=null;try{const p=project();renderGeometry(p);lastResult=null;lastSweep=null;lastOptimizer=null;lastVariant=null;lastMeasurementSet=null;lastReport=null;syncWorkflowButtons();status('геометрия обновлена','ok')}catch{}els.geometryCanvas.releasePointerCapture?.(ev.pointerId)}
function syncGeometryFromProject(p){if(!els.geometryCanvas)return;ensureGeometrySelection(p);renderGeometry(p);if(els.geometryTemplateFrequency&&document.activeElement!==els.geometryTemplateFrequency&&p.frequency_hz)els.geometryTemplateFrequency.value=(Number(p.frequency_hz)/1e6).toFixed(3)}
let geometryTemplates=[];
async function loadGeometryTemplates(){if(!els.geometryTemplate)return;try{const r=await api('/api/templates');geometryTemplates=(r.templates||[]).filter(x=>x.status==='implemented');els.geometryTemplate.innerHTML='';for(const item of geometryTemplates){const o=document.createElement('option');o.value=item.id;o.textContent=item.label;els.geometryTemplate.appendChild(o)}const preferred=geometryTemplates.find(x=>x.id==='yagi-3el')||geometryTemplates[0];if(preferred)els.geometryTemplate.value=preferred.id;syncGeometryTemplateStatus();const p=project();if(p.frequency_hz)els.geometryTemplateFrequency.value=(Number(p.frequency_hz)/1e6).toFixed(3)}catch(e){els.geometryTemplate.innerHTML='<option value="">Шаблоны недоступны</option>';els.geometryTemplateStatus.textContent=String(e.message||e);els.geometryTemplateStatus.classList.remove('ready')}}
function syncGeometryTemplateStatus(){const item=geometryTemplates.find(x=>x.id===els.geometryTemplate?.value);if(!item){els.geometryTemplateStatus.textContent='—';return}els.geometryTemplateStatus.textContent=(item.trust||'experimental')+' · '+(item.use_cases||[]).join(' · ');els.geometryTemplateStatus.classList.toggle('ready',item.trust==='reference-validated'||item.trust==='characterized')}
async function createGeometryTemplate(){try{const id=els.geometryTemplate.value,fmhz=Number(els.geometryTemplateFrequency.value);if(!id)throw new Error('Выберите шаблон');if(!(fmhz>0))throw new Error('Частота должна быть > 0');if(!confirm('Заменить текущую модель шаблоном и выполнить расчёт?'))return;els.geometryTemplateCreate.disabled=true;status('создаю шаблон…');const r=await api('/api/template/'+encodeURIComponent(id)+'?frequency_hz='+encodeURIComponent(fmhz*1e6));const p=r.project;els.editor.value=JSON.stringify(p,null,2);selectedWireId=p.wires?.[0]?.id||null;lastResult=null;lastSweep=null;lastOptimizer=null;lastVariant=null;lastMeasurementSet=null;lastReport=null;updateMeta(p);const mhz=Number(p.frequency_hz)/1e6;els.sweepStart.value=(mhz*.9).toFixed(3);els.sweepStop.value=(mhz*1.1).toFixed(3);els.optBandStart.value=(mhz*.99).toFixed(3);els.optBandStop.value=(mhz*1.01).toFixed(3);status('шаблон создан · проверка…');await check();await run();status('шаблон создан и рассчитан','ok')}catch(e){status('ошибка шаблона','err');els.diag.textContent=String(e.message||e)}finally{els.geometryTemplateCreate.disabled=false}}
function initGeometryEditor(){if(!els.geometryCanvas)return;els.geometryTemplateCreate.onclick=createGeometryTemplate;els.geometryTemplate.addEventListener('change',syncGeometryTemplateStatus);loadGeometryTemplates();document.querySelectorAll('[data-geometry-projection]').forEach(b=>b.addEventListener('click',()=>{geometryProjection=b.dataset.geometryProjection;document.querySelectorAll('[data-geometry-projection]').forEach(x=>x.classList.toggle('active',x===b));try{renderGeometry(project())}catch{}}));els.geometryAdd.onclick=addGeometryWire;els.geometryFeed.onclick=assignGeometryFeed;els.geometryDelete.onclick=deleteGeometryWire;els.geometryCheck.onclick=check;[els.geometrySx,els.geometrySy,els.geometrySz,els.geometryEx,els.geometryEy,els.geometryEz,els.geometryDiameter,els.geometrySegments].forEach(x=>x.addEventListener('change',applyGeometryFields));els.geometryCanvas.addEventListener('pointerdown',geometryPointerDown);els.geometryCanvas.addEventListener('pointermove',geometryPointerMove);els.geometryCanvas.addEventListener('pointerup',geometryPointerUp);els.geometryCanvas.addEventListener('pointercancel',geometryPointerUp);els.editor.addEventListener('input',()=>{try{updateMeta(project())}catch{}})}
function showResult(r){lastResult=r;const f=r.feeds?.[0],p=project(),lossy=(p.wires||[]).filter(w=>Number(w.conductivity_s_per_m||0)>0),loads=p.loads||[];const lossLines=[`Loss model: ${lossy.length?lossy.length+' finite-conductivity wire(s)':'PEC conductors'} · ${loads.length} lumped load(s)`];if(lossy.length)lossLines.push('Conductivity: '+lossy.map(w=>`${w.id||'?'}=${Number(w.conductivity_s_per_m).toExponential(3)} S/m`).join(', '));if(loads.length)lossLines.push('Loads: '+loads.map(x=>`${x.id||'?'}[${x.wire_id||'?'}:${x.segment_index??'?'}] R=${Number(x.resistance_ohm||0)}Ω L=${Number(x.inductance_h||0).toExponential(3)}H C=${Number(x.capacitance_f||0).toExponential(3)}F`).join('; '));els.zin.textContent=cpx(f?.impedance_ohm);els.vswr.textContent=fmt(f?.vswr,3);els.dmax.textContent=fmt(r.summary?.dmax_dbi,3);els.eff.textContent=fmt(100*(r.efficiency??0),3);els.accepted.textContent=Number(r.accepted_power_w||0).toExponential(3);els.radiated.textContent=Number(r.radiated_power_w||0).toExponential(3);els.dissipated.textContent=Number(r.dissipated_power_w||0).toExponential(3);els.balance.textContent=(r.power_balance_relative_error??0).toExponential(2);els.raw.textContent=JSON.stringify(r,null,2);els.diag.textContent=[`Solver: ${r.solver_id} v${r.solver_version}`,`Settings: ${r.solver_settings_id}`,`Model hash: ${r.model_hash}`,...lossLines,`Accepted power: ${r.accepted_power_w} W`,`Radiated power: ${r.radiated_power_w} W`,`Dissipated power: ${r.dissipated_power_w} W`,`Efficiency: ${fmt(100*(r.efficiency??0),4)}%`,'',...(r.warnings||[]).map(x=>'⚠ '+x)].join('\n');drawPolar(r);drawCurrents(r)}
async function run(){setWorkspaceView('solve');try{const p=project();updateMeta(p);document.body.classList.add('busy');els.run.disabled=true;status('расчёт…');const j=await api('/api/solve',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project:p,kernel})});showResult(j.result);status('расчёт завершён','ok')}catch(e){status('ошибка','err');els.diag.textContent=String(e.message||e)}finally{document.body.classList.remove('busy');els.run.disabled=false}}
